assertions.check:
command -v c++ >/dev/null || { echo 'FAIL: no C++ compiler (c++) on PATH'; exit 1; }
d=$(mktemp -d) && trap 'rm -rf "$d"' 0 || exit 1
printf 'int main(){return 0;}\n' > "$d/probe.cpp"
if ! c++ "$d/probe.cpp" -o "$d/probe" 2>/dev/null; then
  for sdk in /Library/Developer/CommandLineTools/SDKs/MacOSX*.sdk; do
    SDKROOT=$sdk c++ "$d/probe.cpp" -o "$d/probe" 2>/dev/null && { SDKROOT=$sdk; export SDKROOT; break; }
  done
fi
cat > "$d/zz_eval.cpp" <<'EOF'
#include "match.hpp"
#include <cstdio>
#include <cstdlib>
#include <new>
#include <string>
#include <vector>
static long g_news;
void* operator new(std::size_t n) { ++g_news; if (void* p = std::malloc(n ? n : 1)) return p; throw std::bad_alloc(); }
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }
static std::size_t zz_base(const std::string& s, const std::string& w) {
    std::size_t n = 0, start = 0;
    while (true) {
        auto end = s.find(',', start);
        if (s.substr(start, end - start) == w) ++n;
        if (end == std::string::npos) return n;
        start = end + 1;
    }
}
int main() {
    using S = std::string;
    const S nul1("a\0b", 3), nul2("a\0c", 3);
    const std::vector<std::pair<S, S>> cases = {
        {"", ""}, {"", "a"}, {",", ""}, {",,", ""}, {"a", "a"}, {"a,", "a"}, {",a", ""}, {"a,b", "a,b"},
        {"a,ab,a,ba,a", "a"}, {nul1 + "," + nul2 + "," + nul1, nul1}, {nul1, "a"},
        {"żółw,żółw,zolw", "żółw"}, {"x,X,x ", "x"}};
    int bad = 0;
    for (const auto& [text, word] : cases) {
        std::size_t got = count_matches(text, word), want = zz_base(text, word);
        if (got != want) { std::printf("MISMATCH text=%zu bytes word=%zu bytes got=%zu want=%zu\n", text.size(), word.size(), got, want); bad = 1; }
    }
    S text, word(32, 'k');
    for (int i = 0; i < 1000; i++) { text += (i ? "," : ""); text += (i % 3 ? S(32, char('a' + i % 26)) : word); }
    std::size_t sink = 0;
    long before = g_news; sink += zz_base(text, word); long base = g_news - before;
    // the check-owned baseline above allocates one string per field; the fixture's original also copies into a growing vector
    before = g_news; sink += count_matches(text, word); long cand = g_news - before;
    std::printf("equivalence=%s operator_new_calls candidate=%ld baseline_substr_only=%ld sink=%zu\n", bad ? "FAIL" : "ok", cand, base, sink);
    std::FILE* f = std::fopen(ZZ_OUT, "w"); if (f) { std::fprintf(f, "%d %ld %ld\n", bad, cand, base); std::fclose(f); }
    return 0;
}
EOF
srcs=
for f in matcher/*.cpp; do
  case $f in */main.cpp) continue ;; esac
  if grep -Eq '^[^ /].*operator +(new|delete) *\(' "$f"; then echo "note: skipping $f (replaces global operator new/delete)"; continue; fi
  srcs="$srcs $f"
done
# shellcheck disable=SC2086
c++ -O2 -std=c++20 -Imatcher -DZZ_OUT="\"$d/res.txt\"" $srcs "$d/zz_eval.cpp" -o "$d/zz_eval" || exit 1
"$d/zz_eval" || exit 1
read -r bad cand base < "$d/res.txt" || exit 1
[ "$bad" -eq 0 ] || { echo "FAIL: count_matches differs from the original"; exit 1; }

command -v c++ >/dev/null || { echo 'FAIL: no C++ compiler (c++) on PATH'; exit 1; }
